let BASE_URL="";function getcookie(){return document.cookie.split("; ").find(t=>t.startsWith("user_cookie="))?.split("=")[1]||"gunmu"}async function getusername(t){return(await(await fetch(BASE_URL+"/api/getinfoshort?key="+t)).json()).username||null}async function getuid(t){return(await(await fetch(BASE_URL+"/api/getinfoshort?key="+t)).json()).uid||null}async function checkLogin(){var e=getcookie(),o=document.getElementById("login-area"),i=document.getElementById("statusIndicator");if(!e||"gunmu"===e)return o.innerHTML=`<button class="login-btn" onclick="window.location.href='/login'">登录</button>`,document.getElementById("statusText").textContent="未登录",!(i.className="status-indicator logged-out");try{if("Y"!==(await(await fetch(BASE_URL+"/api/verifycookie?cookie="+encodeURIComponent(e))).json()).status)return o.innerHTML=`<button class="login-btn" onclick="window.location.href='/login'">登录</button>`,document.getElementById("statusText").textContent="登录失效",!(i.className="status-indicator logged-out");{let n;try{var t=await(await fetch(BASE_URL+"/api/getinfoshort?key="+encodeURIComponent(e))).json();n=t.username}catch(t){console.error(t);var a=parseInt(e[0],10);n="UID : "+e.substring(1,1+a)}return o.innerHTML=`<div class="logged-in">欢迎，${n}</div>`,document.getElementById("statusText").textContent="已登录",document.getElementById("login-status").innerHTML='<div class="status-indicator" id="statusIndicator"><div class="status-indicator logged-in" id="statusIndicator"></div></div><span id="statusText">已登录</span><div class="logout-popup"><button onclick="logout()">登出</button></div>',document.getElementById("login-status").className="logged-in",i.className="status-indicator logged-in",!0}}catch(t){return o.innerHTML=`<button class="login-btn" onclick="window.location.href='/login'">登录</button>`,document.getElementById("statusText").textContent="检查登录状态失败",i.className="status-indicator logged-out",console.error("Error during login check:",t),!1}}function logout(){document.cookie="user_cookie=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;",location.reload()}document.addEventListener("DOMContentLoaded",async()=>{await checkLogin()});